-- ════════════════════════════════════════════════════════════════════════════
-- 0019 · PROD — Producción de gelato, trazabilidad y costeo (Italo)
--
-- Portado de la app original «Italo Reposición» (producciones, produccion_consumos,
-- produccion_lotes, costeo_*). Todo cuelga de empresa_id; se usa solo en empresas con el
-- módulo 'reposicion' (Italo). Las sabores son rep.sabores (0018, R1).
--
-- ┌─ CONTRATO CON REPOSICIÓN (R1, esquema rep) ────────────────────────────────┐
-- │ 1. prod.producciones = una TANDA de un sabor que salió de fábrica ese día   │
-- │    (kg pesados de verdad, no gramos). Columnas que R1 usa:                  │
-- │      id uuid, empresa_id, fecha date, sabor_id, kg, kg_restante, lote.      │
-- │    kg_restante = kg de la tanda que todavía no salieron en un despacho.     │
-- │    Nace igual a kg. rep.despacho_tandas.produccion_id apunta a              │
-- │    prod.producciones.id (sin FK, como declara 0018). El API de reposición   │
-- │    suelta y reparte FIFO (lo más viejo primero) restando/sumando            │
-- │    kg_restante; este módulo SOLO lee rep.despacho_tandas para trazabilidad  │
-- │    y para impedir corregir o borrar una tanda que ya salió en un despacho.  │
-- │ 2. Cámara de la fábrica = suma de kg_restante por sabor. El plan de         │
-- │    producción lo resta de lo que sale mañana (ver modulos/prod/plan.js).    │
-- │ 3. Los sabores NO se crean aquí: POST /api/rep/sabores (R1). Esta migración │
-- │    enlaza cada receta con su sabor por nombre normalizado (sin tildes);     │
-- │    lo que no calza queda con sabor_id NULL y se avisa (prod.enganchar_      │
-- │    recetas devuelve la lista; POST /api/prod/costeo/enganchar la repite).   │
-- └────────────────────────────────────────────────────────────────────────────┘
--
-- ┌─ PUNTO DE INTEGRACIÓN CON INVENTARIO (R3, esquema rinv, 0020) ─────────────┐
-- │ Las EXISTENCIAS de materia prima de fábrica son de R3: rinv.insumos_fab     │
-- │ (stock_actual), rinv.lotes_mec3 (lotes FIFO con vencimiento),               │
-- │ rinv.movimientos (kardex inalterable) y rinv.salida_lotes. Producción NO    │
-- │ guarda existencias propias. Al confirmar el consumo de una tanda, el API    │
-- │ (modulos/prod/existencias.js, único punto de contacto) hace por cada        │
-- │ insumo, en la MISMA transacción:                                            │
-- │   · localiza el insumo en rinv.insumos_fab por (empresa_id, nombre)         │
-- │     —el nombre es la llave común: ambos catálogos salen de la misma lista   │
-- │     de Mec3—; si no existe allá, el consumo se registra igual en            │
-- │     prod.consumos con todo «sin lote» y se avisa «sin inventario»;           │
-- │   · resta stock_actual (puede quedar negativo: un stock en rojo es un dato  │
-- │     útil, no un bloqueo), toma los lotes FIFO (solo tipo 'mec3') y escribe  │
-- │     un renglón 'salida' en rinv.movimientos con el motivo «Tanda <lote>»;   │
-- │   · guarda en prod.produccion_lotes de qué lote de rinv.lotes_mec3 salió.   │
-- │ Corregir o borrar una tanda lo deshace (renglón 'entrada' con el motivo;    │
-- │ el kardex nunca se edita). prod.produccion_lotes.lote_id es un uuid sin FK  │
-- │ a propósito (rinv se crea después, 0020). prod.costeo_insumos/precios son   │
-- │ el catálogo y la lista de precios de COSTEO; R3 puede leerlos por nombre.   │
-- └────────────────────────────────────────────────────────────────────────────┘
--
-- Reglas de costeo preservadas del original (ver modulos/prod/costeo.js):
--   1. Precio vigente de un insumo a una fecha = el más reciente con
--      fecha_vigencia <= fecha (empate: el de mayor id). Sube y baja.
--   2. Costo/kg de una receta = costo total del lote / peso del lote en kg.
--   3. Todo o nada: si falta el precio de UN ingrediente, el costo es NULL.
--   4. El costo de cada tanda se congela con el precio de la fecha de ESA tanda.
--   5. costeo_precios es solo-agrega: un trigger impide UPDATE y DELETE. Los
--      insumos dolarizados guardan usd_kg y el tipo de cambio usado en cada fila.
-- ════════════════════════════════════════════════════════════════════════════

create schema if not exists prod;

-- ─── Contadores por empresa (lote del día, códigos de sabor) ────────────────
create table prod.contadores (
  empresa_id uuid not null references core.empresas(id) on delete cascade,
  clave      text not null,
  valor      bigint not null default 0,
  primary key (empresa_id, clave)
);
create function prod.siguiente(p_empresa uuid, p_clave text) returns bigint language plpgsql as $$
declare v bigint;
begin
  insert into prod.contadores (empresa_id, clave, valor) values (p_empresa, p_clave, 1)
  on conflict (empresa_id, clave) do update set valor = prod.contadores.valor + 1
  returning valor into v;
  return v;
end $$;

-- Código numérico corto de cada sabor (para el código de lote 20261008-12-1).
create table prod.sabor_codigos (
  empresa_id uuid not null references core.empresas(id) on delete cascade,
  sabor_id   uuid not null references rep.sabores(id) on delete cascade,
  codigo     int  not null,
  primary key (empresa_id, sabor_id),
  unique (empresa_id, codigo)
);
create function prod.codigo_sabor(p_empresa uuid, p_sabor uuid) returns int language plpgsql as $$
declare v int;
begin
  select codigo into v from prod.sabor_codigos where empresa_id = p_empresa and sabor_id = p_sabor;
  if v is not null then return v; end if;
  insert into prod.sabor_codigos (empresa_id, sabor_id, codigo)
  values (p_empresa, p_sabor, prod.siguiente(p_empresa, 'sabor')::int)
  on conflict (empresa_id, sabor_id) do nothing;
  select codigo into v from prod.sabor_codigos where empresa_id = p_empresa and sabor_id = p_sabor;
  return v;
end $$;

-- ─── Catálogo de materia prima (insumos de costeo) ──────────────────────────
-- tipo: 'mec3' = materia prima importada (pastas, bases; se cuenta por bote y lleva lote);
--       'local' = lácteos/frutas locales.
create table prod.costeo_insumos (
  id                   uuid primary key default gen_random_uuid(),
  empresa_id           uuid not null references core.empresas(id),
  nombre               text not null,
  tipo                 text not null check (tipo in ('mec3','local')),
  part_number          text,
  unidad               text not null default 'unidad',
  activo               boolean not null default true,
  categoria            text,
  descripcion          text,
  created_at           timestamptz not null default now(),
  unique (empresa_id, nombre)
);
create index prod_costeo_insumos_idx on prod.costeo_insumos (empresa_id) where activo;

-- Historial de precios: SOLO SE AGREGA. lps_kg es el precio en Lempiras por kg; los dolarizados
-- guardan además usd_kg y el tipo de cambio con que se convirtió (lps_kg = usd_kg × tipo_cambio).
create table prod.costeo_precios (
  id                bigserial primary key,
  empresa_id        uuid not null references core.empresas(id),
  insumo_id         uuid not null references prod.costeo_insumos(id),
  fecha_vigencia    date not null,
  lps_kg            numeric(14,4) not null check (lps_kg >= 0),
  usd_kg            numeric(14,4) check (usd_kg is null or usd_kg >= 0),
  tipo_cambio_usado numeric(10,4) check (tipo_cambio_usado is null or tipo_cambio_usado > 0),
  fuente            text not null default 'manual' check (fuente in ('factura_mec3','manual')),
  factura_ref       text,
  usuario_id        uuid references core.usuarios(id),
  created_at        timestamptz not null default now()
);
create index prod_costeo_precios_idx on prod.costeo_precios (insumo_id, fecha_vigencia, id);
create index prod_costeo_precios_emp_idx on prod.costeo_precios (empresa_id);
create function prod.precios_solo_agrega() returns trigger language plpgsql as $$
begin
  raise exception 'El historial de precios no se edita ni se borra: agrega un precio nuevo';
end $$;
create trigger costeo_precios_solo_agrega before update or delete on prod.costeo_precios
  for each row execute function prod.precios_solo_agrega();

-- ─── Recetas (una por sabor) ────────────────────────────────────────────────
-- sabor_id NULL = receta sembrada que todavía no engancha con un sabor del catálogo.
create table prod.costeo_recetas (
  id              uuid primary key default gen_random_uuid(),
  empresa_id      uuid not null references core.empresas(id),
  nombre          text not null,
  sabor_id        uuid references rep.sabores(id) on delete set null,
  precio_venta_kg numeric(14,2) check (precio_venta_kg is null or precio_venta_kg >= 0),   -- opcional: para el margen
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (empresa_id, nombre),
  unique (empresa_id, sabor_id)
);
create table prod.receta_insumos (
  id         uuid primary key default gen_random_uuid(),
  receta_id  uuid not null references prod.costeo_recetas(id) on delete cascade,
  insumo_id  uuid not null references prod.costeo_insumos(id),
  gramos     numeric(12,3) not null check (gramos > 0)
);
create index prod_receta_insumos_idx on prod.receta_insumos (receta_id);
create index prod_receta_insumos_insumo_idx on prod.receta_insumos (insumo_id);

-- ─── Tandas de producción ───────────────────────────────────────────────────
-- Un renglón = una tanda de un sabor. El lote (fecha + código de sabor + n.º de tanda del día)
-- identifica la tanda en la etiqueta y en la trazabilidad.
create table prod.producciones (
  id                    uuid primary key default gen_random_uuid(),
  empresa_id            uuid not null references core.empresas(id),
  fecha                 date not null,
  sabor_id              uuid not null references rep.sabores(id),
  kg                    numeric(10,3) not null check (kg > 0 and kg <= 500),
  panas                 numeric(6,2) check (panas is null or panas > 0),   -- informativo: panas que equivale
  kg_restante           numeric(10,3) not null default 0,                  -- sin despachar (ver contrato 1)
  lote                  text not null,
  operario              text not null default '',
  notas                 text not null default '',
  costo_kg_congelado    numeric(14,4),
  costo_total_congelado numeric(14,2),
  cliente_id            text,                                             -- idempotencia: reintento sin señal
  usuario_id            uuid references core.usuarios(id),
  created_at            timestamptz not null default now(),
  unique (empresa_id, lote)
);
create index prod_producciones_fecha_idx on prod.producciones (empresa_id, fecha);
create index prod_producciones_sabor_idx on prod.producciones (empresa_id, sabor_id, fecha);
create unique index prod_producciones_cliente_idx on prod.producciones (empresa_id, cliente_id) where cliente_id is not null;

-- ─── Consumo de materia prima por tanda ─────────────────────────────────────
-- Se guardan las DOS cifras: lo que decía la receta (sugerida; NULL = el sabor no tenía receta,
-- distinto de 0) y lo que de verdad se usó. sin_lote = parte que no se pudo atribuir a un lote.
create table prod.consumos (
  id                uuid primary key default gen_random_uuid(),
  empresa_id        uuid not null references core.empresas(id),
  produccion_id     uuid not null references prod.producciones(id) on delete cascade,
  insumo_id         uuid not null references prod.costeo_insumos(id),
  cantidad_sugerida numeric(14,4),
  cantidad_real     numeric(14,4) not null check (cantidad_real > 0),
  sin_lote          numeric(14,4) not null default 0,
  rinv_insumo_id    uuid,                       -- rinv.insumos_fab(id) al que se le descontó; NULL = no había inventario
  created_at        timestamptz not null default now(),
  unique (produccion_id, insumo_id)
);
create index prod_consumos_insumo_idx on prod.consumos (insumo_id);

-- Qué lote de materia prima alimentó qué tanda, y cuánto.
create table prod.produccion_lotes (
  id            uuid primary key default gen_random_uuid(),
  empresa_id    uuid not null references core.empresas(id),
  produccion_id uuid not null references prod.producciones(id) on delete cascade,
  lote_id       uuid not null,                       -- rinv.lotes_mec3(id), sin FK (ver contrato)
  insumo_id     uuid not null references prod.costeo_insumos(id),
  cantidad      numeric(14,3) not null check (cantidad > 0)
);
create index prod_produccion_lotes_lote_idx on prod.produccion_lotes (lote_id);
create index prod_produccion_lotes_prod_idx on prod.produccion_lotes (produccion_id);

-- ─── Seguridad: RLS activa y sin políticas (solo el API entra) ──────────────
alter table prod.contadores         enable row level security;
alter table prod.sabor_codigos      enable row level security;
alter table prod.costeo_insumos     enable row level security;
alter table prod.costeo_precios     enable row level security;
alter table prod.costeo_recetas     enable row level security;
alter table prod.receta_insumos     enable row level security;
alter table prod.producciones       enable row level security;
alter table prod.consumos           enable row level security;
alter table prod.produccion_lotes   enable row level security;

-- ─── Enganche de recetas con sabores ────────────────────────────────────────
create function prod.norm(t text) returns text language sql immutable as $$
  select upper(btrim(regexp_replace(translate(coalesce(t, ''), 'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'), '\s+', ' ', 'g')))
$$;

-- Engancha cada receta sin sabor con el sabor de rep.sabores del mismo nombre normalizado.
-- Alias del original: FRUTTI DI BOSCO = FRUTOS ROJOS (italiano) y WHISKY SMOGGLERS = WHISKY.
-- Devuelve { enganchadas: n, sin_sabor: [nombres] } para avisar lo que no calzó.
create function prod.enganchar_recetas(p_empresa uuid) returns jsonb language plpgsql as $$
declare r record; v_sabor uuid; v_clave text; n int := 0; sin jsonb := '[]'::jsonb;
begin
  for r in select id, nombre from prod.costeo_recetas where empresa_id = p_empresa and sabor_id is null order by nombre loop
    v_clave := case prod.norm(r.nombre)
      when 'FRUTTI DI BOSCO' then 'FRUTOS ROJOS'
      when 'WHISKY SMOGGLERS' then 'WHISKY'
      else prod.norm(r.nombre) end;
    select s.id into v_sabor from rep.sabores s
     where s.empresa_id = p_empresa and prod.norm(s.nombre) = v_clave
       and not exists (select 1 from prod.costeo_recetas x where x.empresa_id = p_empresa and x.sabor_id = s.id)
     limit 1;
    if v_sabor is not null then
      update prod.costeo_recetas set sabor_id = v_sabor, updated_at = now() where id = r.id;
      n := n + 1;
    else
      sin := sin || to_jsonb(r.nombre);
    end if;
  end loop;
  return jsonb_build_object('enganchadas', n, 'sin_sabor', sin);
end $$;

-- ─── Siembra idempotente del costeo «Italo costos y fórmulas» ───────────────
-- p_datos = { insumos: [{nombre,tipo,part_number,unidad,lps_kg,usd_kg,fecha_vigencia,fuente,factura_ref}],
--             recetas: { "NOMBRE": [{insumo, gramos}] } }
-- Correrla de nuevo no duplica nada ni pisa una receta ya cargada.
create function prod.sembrar_costeo(p_empresa uuid, p_datos jsonb) returns jsonb language plpgsql as $$
declare
  i record; r record; it record;
  v_id uuid; v_receta uuid;
  insumos_creados int := 0; precios_creados int := 0; recetas_creadas int := 0; ingredientes_creados int := 0;
  no_encontrados jsonb := '[]'::jsonb; eng jsonb;
begin
  for i in select * from jsonb_to_recordset(p_datos->'insumos')
      as x(nombre text, tipo text, part_number text, unidad text, lps_kg numeric, usd_kg numeric, fecha_vigencia date, fuente text, factura_ref text) loop
    v_id := null;
    insert into prod.costeo_insumos (empresa_id, nombre, tipo, part_number, unidad)
    values (p_empresa, upper(btrim(i.nombre)), i.tipo, i.part_number, coalesce(i.unidad, 'unidad'))
    on conflict (empresa_id, nombre) do nothing
    returning id into v_id;
    if v_id is not null then insumos_creados := insumos_creados + 1;
    else select id into v_id from prod.costeo_insumos where empresa_id = p_empresa and nombre = upper(btrim(i.nombre)); end if;

    if i.lps_kg is not null and not exists (
         select 1 from prod.costeo_precios where insumo_id = v_id and fecha_vigencia = i.fecha_vigencia and lps_kg = i.lps_kg) then
      insert into prod.costeo_precios (empresa_id, insumo_id, fecha_vigencia, lps_kg, usd_kg, tipo_cambio_usado, fuente, factura_ref)
      values (p_empresa, v_id, i.fecha_vigencia, i.lps_kg, i.usd_kg,
              case when i.usd_kg > 0 then round(i.lps_kg / i.usd_kg, 4) end,
              coalesce(i.fuente, 'manual'), i.factura_ref);
      precios_creados := precios_creados + 1;
    end if;
  end loop;

  for r in select key as nombre, value as items from jsonb_each(p_datos->'recetas') loop
    v_receta := null;
    insert into prod.costeo_recetas (empresa_id, nombre) values (p_empresa, r.nombre)
    on conflict (empresa_id, nombre) do nothing
    returning id into v_receta;
    if v_receta is null then continue; end if;      -- ya existía: no se pisa
    recetas_creadas := recetas_creadas + 1;
    for it in select * from jsonb_to_recordset(r.items) as y(insumo text, gramos numeric) loop
      select id into v_id from prod.costeo_insumos where empresa_id = p_empresa and prod.norm(nombre) = prod.norm(it.insumo) limit 1;
      if v_id is null then
        no_encontrados := no_encontrados || to_jsonb(r.nombre || ' -> ' || it.insumo);
      else
        insert into prod.receta_insumos (receta_id, insumo_id, gramos) values (v_receta, v_id, it.gramos);
        ingredientes_creados := ingredientes_creados + 1;
      end if;
    end loop;
  end loop;

  eng := prod.enganchar_recetas(p_empresa);
  return jsonb_build_object('insumos_creados', insumos_creados, 'precios_creados', precios_creados,
    'recetas_creadas', recetas_creadas, 'ingredientes_creados', ingredientes_creados,
    'insumo_no_encontrado', no_encontrados, 'enganchadas', eng->'enganchadas', 'sin_sabor', eng->'sin_sabor');
end $$;

-- ─── Semilla: 303 insumos con su precio vigente y 24 recetas (solo Italo) ───
